import{_ as e,C as o,o as s,c as r,a5 as n,E as c}from"./chunks/framework.CX7j2CRp.js";const E=JSON.parse('{"title":"加密记录","description":"在浏览器本地维护支持多个长期独立密钥的加密记录。","frontmatter":{"title":"加密记录","description":"在浏览器本地维护支持多个长期独立密钥的加密记录。"},"headers":[],"relativePath":"pages/vault.md","filePath":"pages/vault.md","lastUpdated":1790737604000}'),d={name:"pages/vault.md"};function l(p,t,_,i,u,m){const a=o("EstateVault");return s(),r("div",null,[t[0]||(t[0]=n('<h1 id="加密记录" tabindex="-1">加密记录 <a class="header-anchor" href="#加密记录" aria-label="Permalink to &quot;加密记录&quot;">​</a></h1><p>这是一份可公开分发的加密记录。外层使用 Base64 文本封装，仓库中只保存一个普通的 <code>data.dat</code> 数据文件。首次创建时生成一把随机 DEK，并由多个家人密钥分别包裹；以后每次更新正文都复用原 DEK 和原全部密钥槽，只重新生成正文的 AES-GCM IV 与密文。</p><p>因此，只要没有主动做密钥轮换，<strong>第一次发给家人的恢复密钥可以长期保持有效</strong>。</p><blockquote><p>所有加解密都在浏览器本地完成。将生成的 Base64 数据保存到 <code>public/assets/data.dat</code> 并提交；GitHub Actions 只负责构建和发布密文，不需要任何解密密钥。</p></blockquote>',4)),c(a)])}const h=e(d,[["render",l]]);export{E as __pageData,h as default};
